 const same=(s,ids)=>{for(const id of ids)for(const key of ["color","background","fill"])assert(s[id][key]===baseline[id][key],id+" unexpectedly followed unrelated semantic override: "+key)};
 await test({"--hub-color-surface-button":sentinel,"--hub-color-surface-button-hover":"rgb(30, 120, 180)"},s=>{for(const id of ["music","statistics","workspace"])assert(s[id].background===sentinel,id+" dropdown surface remained host-resolved");assert(view.getComputedStyle(root).getPropertyValue("--dropdown-background-hover").trim()==="rgb(30, 120, 180)","Dropdown hover alias");});
 await test({"--hub-color-text-muted":sentinel},()=>{for(const id of ["date","datetime"])assert(view.getComputedStyle(at(id)).getPropertyValue("--input-date-separator").trim()===sentinel,id+" punctuation alias");});
 await test({"--hub-color-accent":sentinel},s=>{assert(s.quote.border.includes(sentinel),"Quote retained host accent");same(s,["oath-active","oath-action","must","should","task-series","step-series","heat-4","heat-9","heat-16"]);});
 await test({"--hub-color-border":sentinel},s=>{assert(s.hr.border.includes(sentinel),"Rule retained host border");assert(s.code.border.includes(sentinel),"Code retained host border (even at zero width)");});
 await test({"--hub-color-error":sentinel},s=>{for(const id of ["task-error","music-error","athena-error","explorer-error"])assert(s[id].color===sentinel,id+" error role");for(const id of ["create-error","placeholder-error"])assert(s[id].border.includes(sentinel),id+" validation border");assert(s["placeholder-error"].color===sentinel&&s["placeholder-error"].shadow.includes(sentinel),"Inline validation paint");same(s,["must","should","overdue","deleted","native-danger","capture-danger"]);});
 await test({"--hub-color-destructive":sentinel},s=>{for(const id of ["native-danger","capture-danger"])assert(s[id].background===sentinel,id+" destructive fill");same(s,["task-error","must","overdue","deleted"]);});
 await test({"--hub-color-success":sentinel},s=>{for(const id of ["home-complete","project-complete","report-complete"])assert(s[id].color===sentinel,id+" completion role");assert(s["task-series"].fill===sentinel,"Completion series role");same(s,["created","checkbox","heat-4","heat-9","heat-16","step-series"]);});
 await test({"--hub-color-activity-edited":sentinel},s=>{for(const id of ["home-edited","project-edited","report-edited"])assert(s[id].color===sentinel,id+" edited role");same(s,["step-series","task-series","deleted"]);});
 await test({"--hub-color-series-step-completion":sentinel},s=>{assert(s["step-series"].fill===sentinel,"Step series override");same(s,["home-edited","project-edited","report-edited","task-series"]);});
 await test({"--hub-color-warning":sentinel},s=>{for(const id of ["calendar-warning","location-warning","conflict-warning","manual-warning"])assert(s[id].color===sentinel,id+" warning role");assert(s["warning-border"].border.includes(sentinel),"Warning border");same(s,["should","must","overdue","native-danger"]);});
 await test({"--hub-color-accent-hover":sentinel},s=>{same(s,["accent-text"]);assert(view.getComputedStyle(root).getPropertyValue("--interactive-accent-hover").trim()===sentinel,"Hover fill override");});
 await test({"--hub-color-accent-text":sentinel},s=>{assert(s["accent-text"].color===sentinel,"Accent text override");assert(view.getComputedStyle(root).getPropertyValue("--interactive-accent-hover").trim()===hoverBefore,"Accent text changed hover fill");});
