 await test({"--hub-color-text-on-accent":sentinel},s=>{assert(s.selected.color===sentinel,"Selected on-accent role");same(s,["ordinary-action","native-danger","capture-danger","oath-action"]);});
 await test({"--hub-color-primary-action-text":sentinel},s=>{assert(s["ordinary-action"].color===sentinel,"Primary-action foreground role");same(s,["selected","native-danger","capture-danger","oath-action"]);});
 await test({"--hub-color-text-on-destructive":sentinel},s=>{for(const id of ["native-danger","capture-danger"])assert(s[id].color===sentinel,id+" destructive foreground role");same(s,["ordinary-action","oath-action"]);});
 await test({"--hub-roadmap-phase-end":sentinel},s=>{assert(s["phase-end"].background===sentinel,"Roadmap endpoint override");same(s,["home-edited","step-series"]);});
 const unowned=createColorConsistencyGallery(doc);doc.body.append(unowned);const hostBefore=consistencySnapshot(unowned);
 await test({"--hub-color-error":sentinel,"--hub-color-surface-button":sentinel},()=>{const after=consistencySnapshot(unowned);for(const id of ["music","statistics","task-error"])assert(JSON.stringify(after[id])===JSON.stringify(hostBefore[id]),"Unowned host changed: "+id)});unowned.remove();
 const island=doc.createElement("div");root.append(island);const release=colors.hostColorIsland(island);island.innerHTML='<select class="dropdown"><option>Excluded</option></select><input type="datetime-local"><blockquote></blockquote><hr><code></code><button class="mod-warning">Host destructive action</button>';
 await test({"--hub-color-surface-button":sentinel,"--hub-color-accent":sentinel,"--hub-color-border":sentinel,"--hub-color-text-muted":sentinel},()=>{for(const name of ["--dropdown-background","--dropdown-background-hover","--input-date-separator","--blockquote-border-color","--hr-color","--code-border-color"])assert(view.getComputedStyle(island).getPropertyValue(name).trim()===view.getComputedStyle(doc.body).getPropertyValue(name).trim(),"Host island leaked "+name);const danger=view.getComputedStyle(island.querySelector("button"));assert(danger.color===hostBefore["native-danger"].color,"Host island destructive foreground leaked");assert(danger.backgroundColor===hostBefore["native-danger"].background,"Host island destructive fill leaked");});release();island.remove();
 const bodyStyle=doc.body.getAttribute("style"),before=consistencySnapshot(root);try{for(const name of ["--dropdown-background","--dropdown-background-hover","--input-date-separator","--blockquote-border-color","--hr-color","--code-border-color"])doc.body.style.setProperty(name,sentinel);await wait();const after=consistencySnapshot(root);for(const id of ["music","statistics","workspace","date","datetime","quote","hr","code"])assert(JSON.stringify(before[id])===JSON.stringify(after[id]),"Owned host alias leak "+id);}finally{bodyStyle===null?doc.body.removeAttribute("style"):doc.body.setAttribute("style",bodyStyle);}
